    content.innerHTML=shell('Website content','Update approved public homepage content without editing code.',`<div class="platform-grid"><section class="panel panel-pad p-span-7"><div class="panel-head"><div><h2>Homepage controls</h2><p>The preview updates while you type; nothing publishes until you press the button.</p></div>${chip('Secure publishing','open')}</div><form class="platform-form" id="site-settings-form"><div class="field full"><label class="choice"><input id="site-announcement-enabled" type="checkbox" name="announcement_enabled" ${s.announcement_enabled?'checked':''}> Show announcement bar</label></div><div class="field full"><label for="site-announcement">Announcement</label><input class="input" id="site-announcement" name="announcement_text" value="${esc(s.announcement_text)}" maxlength="180" required></div><div class="field"><label for="site-enrolment-status">Enrolment status</label><select id="site-enrolment-status" name="enrolment_status"><option value="open" ${s.enrolment_status==='open'?'selected':''}>Enrolments open</option><option value="limited" ${s.enrolment_status==='limited'?'selected':''}>Limited places</option><option value="waitlist" ${s.enrolment_status==='waitlist'?'selected':''}>Waitlist only</option></select></div><div class="field"><label for="site-hero-eyebrow">Hero eyebrow</label><input class="input" id="site-hero-eyebrow" name="hero_eyebrow" value="${esc(s.hero_eyebrow)}" required></div><div class="field"><label for="site-hero-heading">Headline</label><input class="input" id="site-hero-heading" name="hero_heading" value="${esc(s.hero_heading)}" required></div><div class="field"><label for="site-hero-accent">Accent line</label><input class="input" id="site-hero-accent" name="hero_accent" value="${esc(s.hero_accent)}" required></div><div class="field full"><label for="site-hero-intro">Homepage introduction</label><textarea id="site-hero-intro" name="hero_intro" maxlength="360" required>${esc(s.hero_intro)}</textarea></div><div class="field full"><label for="site-primary-cta">Main button label</label><input class="input" id="site-primary-cta" name="primary_cta" value="${esc(s.primary_cta)}" maxlength="50" required></div><div class="field full"><button class="btn btn-blue" type="submit">Publish website changes</button></div></form></section><section class="panel panel-pad p-span-5"><div class="panel-head"><h2>Live preview</h2><a class="btn btn-soft btn-small" href="index.html" target="_blank" rel="noopener">Open website</a></div><div class="site-preview" aria-label="Homepage content preview"><span data-site-preview="hero_eyebrow">${esc(s.hero_eyebrow)}</span><h3><span data-site-preview="hero_heading">${esc(s.hero_heading)}</span><em data-site-preview="hero_accent">${esc(s.hero_accent)}</em></h3><p data-site-preview="hero_intro">${esc(s.hero_intro)}</p><strong><span data-site-preview="primary_cta">${esc(s.primary_cta)}</span> →</strong></div><div class="data-boundary"><strong>Publishing boundary:</strong> This editor controls approved homepage fields. Structural design, imagery, policies and integrations remain developer-managed so the site cannot be accidentally broken.</div></section></div>`);
    const form=document.getElementById('site-settings-form');
